/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_people_after_insert` AFTER INSERT ON `tb_people` FOR EACH ROW BEGIN
    INSERT INTO `tb_logs`
        (`table_name`, `table_operation`, `db_users`, `operation_date`,
         `table_description`, `operation_status`)
    VALUES
        ('tb_people', 'Create', USER(), CURRENT_TIMESTAMP,
         CONCAT(
             'Persona creada. person_ID=', NEW.person_ID,
             ', user_ID=', COALESCE(CAST(NEW.user_ID AS CHAR), 'NULL'),
             ', courtesy_title=', COALESCE(NEW.courtesy_title, 'NULL'),
             ', given_names=', NEW.given_names,
             ', family_names=', COALESCE(NEW.family_names, 'NULL'),
             ', birth_date=', COALESCE(CAST(NEW.birth_date AS CHAR), 'NULL'),
             ', gender=', NEW.gender,
             ', country_code=', COALESCE(NEW.country_code, 'NULL'),
             ', phone=', COALESCE(NEW.phone, 'NULL'),
             ', status=', IF(NEW.status IS NULL, 'NULL', CAST(NEW.status AS UNSIGNED)),
             ', creation_date=', COALESCE(CAST(NEW.creation_date AS CHAR), 'NULL'),
             ', last_update=', COALESCE(CAST(NEW.last_update AS CHAR), 'NULL')
         ),
         b'1');
END */;;
DELIMITER ;
