/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_people_after_update` AFTER UPDATE ON `tb_people` FOR EACH ROW BEGIN
    INSERT INTO `tb_logs`
        (`table_name`, `table_operation`, `db_users`, `operation_date`,
         `table_description`, `operation_status`)
    VALUES
        ('tb_people', 'Update', USER(), CURRENT_TIMESTAMP,
         CONCAT(
             'Persona modificada. person_ID=', NEW.person_ID,
             ' | user_ID: ', COALESCE(CAST(OLD.user_ID AS CHAR), 'NULL'),
                 ' -> ', COALESCE(CAST(NEW.user_ID AS CHAR), 'NULL'),
             ' | courtesy_title: ', COALESCE(OLD.courtesy_title, 'NULL'),
                 ' -> ', COALESCE(NEW.courtesy_title, 'NULL'),
             ' | given_names: ', OLD.given_names, ' -> ', NEW.given_names,
             ' | family_names: ', COALESCE(OLD.family_names, 'NULL'),
                 ' -> ', COALESCE(NEW.family_names, 'NULL'),
             ' | birth_date: ', COALESCE(CAST(OLD.birth_date AS CHAR), 'NULL'),
                 ' -> ', COALESCE(CAST(NEW.birth_date AS CHAR), 'NULL'),
             ' | gender: ', OLD.gender, ' -> ', NEW.gender,
             ' | country_code: ', COALESCE(OLD.country_code, 'NULL'),
                 ' -> ', COALESCE(NEW.country_code, 'NULL'),
             ' | phone: ', COALESCE(OLD.phone, 'NULL'),
                 ' -> ', COALESCE(NEW.phone, 'NULL'),
             ' | status: ',
                 IF(OLD.status IS NULL, 'NULL', CAST(OLD.status AS UNSIGNED)),
                 ' -> ',
                 IF(NEW.status IS NULL, 'NULL', CAST(NEW.status AS UNSIGNED)),
             ' | last_update: ', COALESCE(CAST(OLD.last_update AS CHAR), 'NULL'),
                 ' -> ', COALESCE(CAST(NEW.last_update AS CHAR), 'NULL')
         ),
         b'1');
END */;;
