/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_people_after_delete` AFTER DELETE ON `tb_people` FOR EACH ROW BEGIN
    INSERT INTO `tb_logs`
        (`table_name`, `table_operation`, `db_users`, `operation_date`,
         `table_description`, `operation_status`)
    VALUES
        ('tb_people', 'Delete', USER(), CURRENT_TIMESTAMP,
         CONCAT(
             'Persona eliminada. person_ID=', OLD.person_ID,
             ', user_ID=', COALESCE(CAST(OLD.user_ID AS CHAR), 'NULL'),
             ', courtesy_title=', COALESCE(OLD.courtesy_title, 'NULL'),
             ', given_names=', OLD.given_names,
             ', family_names=', COALESCE(OLD.family_names, 'NULL'),
             ', birth_date=', COALESCE(CAST(OLD.birth_date AS CHAR), 'NULL'),
             ', gender=', OLD.gender,
             ', country_code=', COALESCE(OLD.country_code, 'NULL'),
             ', phone=', COALESCE(OLD.phone, 'NULL'),
             ', status=', IF(OLD.status IS NULL, 'NULL', CAST(OLD.status AS UNSIGNED))
         ),
         b'1');
END */;;
DELIMITER ;
