/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_user_addresses_after_delete` AFTER DELETE ON `tb_user_addresses` FOR EACH ROW BEGIN
    INSERT INTO `tb_logs`
        (`table_name`, `table_operation`, `db_users`, `operation_date`,
         `table_description`, `operation_status`)
    VALUES
        ('tb_user_addresses', 'Delete', USER(), CURRENT_TIMESTAMP,
         CONCAT(
             'Direccion eliminada. ID=', OLD.ID,
             ', user_ID=', OLD.user_ID,
             ', address_label=', OLD.address_label,
             ', recipient_name=', COALESCE(OLD.recipient_name, 'NULL'),
             ', recipient_phone=', COALESCE(OLD.recipient_phone, 'NULL'),
             ', delivery_instructions=', COALESCE(OLD.delivery_instructions, 'NULL'),
             ', latitude=', COALESCE(CAST(OLD.latitude AS CHAR), 'NULL'),
             ', longitude=', COALESCE(CAST(OLD.longitude AS CHAR), 'NULL'),
             ', is_default=', CAST(OLD.is_default AS UNSIGNED),
             ', status=', CAST(OLD.status AS UNSIGNED)
         ),
         b'1');
END */;;
